mapper.select:
select pr.*, u.name as user_name, p.name as product_name, p.product_no, p.cover_image, so.order_no
from product_review pr
left join `user` u on pr.user_id = u.id
left join product p on pr.product_id = p.id
left join shop_order so on pr.order_id = so.id

     and pr.user_id = #{userId}
     and pr.order_id = #{orderId}
     and pr.order_item_id = #{orderItemId}
     and pr.product_id = #{productId}
     and pr.rating = #{rating}
     and pr.audit_status = #{auditStatus}
     and p.name like concat('%', #{productName}, '%')
     and so.order_no like concat('%', #{orderNo}, '%')

order by pr.id desc

mapper.update:
update product_review
rating = #{rating}, content = #{content}, images = #{images}, audit_status = #{auditStatus}, update_time = #{updateTime},
where id = #{id}
